body.query:
query($owner: String!, $repo: String!, $number: Int!) {
  repository(owner: $owner, name: $repo) {
    pullRequest(number: $number) {
      number
      headRefOid
      baseRefOid
      reviews(first: 20) {
        nodes {
          id
          databaseId
          state
          url
          body
          submittedAt
          lastEditedAt
          commit { oid }
          comments(first: 20) {
            nodes {
              id
              databaseId
              url
              state
              body
              path
              line
              originalLine
              position
              originalPosition
              outdated
              lastEditedAt
              commit { oid }
              originalCommit { oid }
            }
          }
        }
      }
      reviewThreads(first: 20) {
        nodes {
          id
          isOutdated
          isResolved
          path
          line
          originalLine
          diffSide
          comments(first: 20) {
            nodes { id databaseId url state }
          }
        }
      }
    }
  }
}
